// Type declaration for @payhere/payhere-mobilesdk-reactnative
// The SDK does not ship with TypeScript types, so we declare them manually.

declare module '@payhere/payhere-mobilesdk-reactnative' {
  export interface PayHerePaymentObject {
    sandbox: boolean;
    merchant_id: string;
    notify_url: string;
    order_id: string;
    items: string;
    amount: string;       // Must be formatted to exactly 2 decimal places e.g. "1000.00"
    currency: string;     // e.g. "LKR"
    hash: string;         // MD5 hash generated by your backend
    first_name: string;
    last_name: string;
    email: string;
    phone: string;
    address: string;
    city: string;
    country: string;
    // Optional: for recurring/preapproval payments
    recurrence?: string;
    duration?: string;
    startup_fee?: string;
  }

  const PayHere: {
    startPayment: (
      paymentObject: PayHerePaymentObject,
      onSuccess: (paymentId: string) => void,
      onError: (errorMessage: string) => void,
      onDismissed: () => void
    ) => void;
  };

  export default PayHere;
}
